import traceback

print(f"Running router on {eval_count} eval rows...")
print(f"This may take several minutes (LLM judge call per row).\n")

results = []
errors = []

for i, row in enumerate(eval_rows):
    eval_id = row["id"]
    prompt = row["prompt"]
    
    try:
        router_output = run_router(prompt)
        results.append({
            "eval_id": eval_id,
            "prompt": prompt,
            "category": row["category"],
            "expected_lane": row["expected_lane"],
            "expected_corpus_id": row["expected_corpus_id"],
            "difficulty": row["difficulty"],
            "predicted_lane": router_output["lane"],
            "predicted_confidence": router_output["confidence"],
            "predicted_corpus_id": router_output["corpus_id"],
            "predicted_badge": router_output["badge"],
            "top_candidate_question": router_output["top_candidate_question"],
            "vs_score": router_output["vs_score"],
            "latency_ms": router_output["latency_ms"],
            "short_circuit": router_output["short_circuit"],
            "is_correct": router_output["lane"] == row["expected_lane"],
            "error": None,
        })
    except Exception as e:
        error_msg = f"{type(e).__name__}: {str(e)[:200]}"
        errors.append({"eval_id": eval_id, "error": error_msg})
        results.append({
            "eval_id": eval_id,
            "prompt": prompt,
            "category": row["category"],
            "expected_lane": row["expected_lane"],
            "expected_corpus_id": row["expected_corpus_id"],
            "difficulty": row["difficulty"],
            "predicted_lane": "error",
            "predicted_confidence": 0.0,
            "predicted_corpus_id": None,
            "predicted_badge": "ERROR",
            "top_candidate_question": None,
            "vs_score": 0.0,
            "latency_ms": 0,
            "short_circuit": False,
            "is_correct": False,
            "error": error_msg,
        })
    
    # Progress every 25 rows
    if (i + 1) % 25 == 0:
        correct_so_far = sum(1 for r in results if r["is_correct"])
        print(f"  [{i+1}/{eval_count}] Accuracy: {correct_so_far}/{len(results)} ({correct_so_far/len(results)*100:.1f}%)")

print(f"\nCompleted: {len(results)} rows processed, {len(errors)} errors")

