# MAGIC %md
# MAGIC ## Compute Metrics

# COMMAND ----------

import mlflow
from pyspark.sql.types import *

# Create results DataFrame
results_schema = StructType([
    StructField("eval_id", StringType()),
    StructField("prompt", StringType()),
    StructField("category", StringType()),
    StructField("expected_lane", StringType()),
    StructField("expected_corpus_id", StringType()),
    StructField("difficulty", StringType()),
    StructField("predicted_lane", StringType()),
    StructField("predicted_confidence", FloatType()),
    StructField("predicted_corpus_id", StringType()),
    StructField("predicted_badge", StringType()),
    StructField("top_candidate_question", StringType()),
    StructField("vs_score", FloatType()),
    StructField("latency_ms", IntegerType()),
    StructField("short_circuit", BooleanType()),
    StructField("is_correct", BooleanType()),
    StructField("error", StringType()),
])

results_df = spark.createDataFrame(results, schema=results_schema)

# --- Primary Metrics ---
valid_results = [r for r in results if r["predicted_lane"] != "error"]
total_valid = len(valid_results)

tp = sum(1 for r in valid_results if r["expected_lane"] == "certified" and r["predicted_lane"] == "certified")
fp = sum(1 for r in valid_results if r["expected_lane"] == "analytical" and r["predicted_lane"] == "certified")
fn = sum(1 for r in valid_results if r["expected_lane"] == "certified" and r["predicted_lane"] == "analytical")
tn = sum(1 for r in valid_results if r["expected_lane"] == "analytical" and r["predicted_lane"] == "analytical")

precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0
accuracy = (tp + tn) / total_valid if total_valid > 0 else 0.0

# Staleness enforcement
stale_results = [r for r in valid_results if r["category"] == "stale_entry_test"]
stale_correct = sum(1 for r in stale_results if r["predicted_lane"] == "analytical")
staleness_enforcement = stale_correct / len(stale_results) if stale_results else 1.0

# --- Secondary Metrics ---
positive_confidences = [r["predicted_confidence"] for r in valid_results if r["expected_lane"] == "certified"]
negative_confidences = [r["predicted_confidence"] for r in valid_results if r["expected_lane"] == "analytical"]

mean_confidence_positives = sum(positive_confidences) / len(positive_confidences) if positive_confidences else 0.0
mean_confidence_negatives = sum(negative_confidences) / len(negative_confidences) if negative_confidences else 0.0

near_miss_results = [r for r in valid_results if r["category"] == "near_miss_negative"]
near_miss_rejected = sum(1 for r in near_miss_results if r["predicted_lane"] == "analytical")
near_miss_rejection_rate = near_miss_rejected / len(near_miss_results) if near_miss_results else 1.0

adversarial_results = [r for r in valid_results if r["category"] == "adversarial"]
adversarial_rejected = sum(1 for r in adversarial_results if r["predicted_lane"] == "analytical")
adversarial_rejection_rate = adversarial_rejected / len(adversarial_results) if adversarial_results else 1.0

retrieval_results = [r for r in valid_results if r["expected_corpus_id"] is not None]
retrieval_hits = sum(1 for r in retrieval_results if r["predicted_corpus_id"] == r["expected_corpus_id"])
retrieval_hit_rate = retrieval_hits / len(retrieval_results) if retrieval_results else 0.0

latencies = sorted([r["latency_ms"] for r in valid_results])
latency_p95 = latencies[int(len(latencies) * 0.95)] if latencies else 0

# --- Print Summary ---
print("=" * 60)
print("  EVALUATION RESULTS")
print("=" * 60)
print(f"\n  Total eval rows:    {eval_count}")
print(f"  Valid results:      {total_valid}")
print(f"  Errors:             {len(errors)}")
print(f"\n  --- Confusion Matrix ---")
print(f"  TP (correct certified):   {tp}")
print(f"  FP (wrong certified):     {fp}")
print(f"  FN (missed certified):    {fn}")
print(f"  TN (correct analytical):  {tn}")
print(f"\n  --- Primary Metrics (Deployment Gate) ---")
print(f"  Gate Precision:     {precision:.4f}  (target: >= 0.95) {'PASS' if precision >= 0.95 else 'FAIL'}")
print(f"  Gate Recall:        {recall:.4f}  (target: >= 0.80) {'PASS' if recall >= 0.80 else 'FAIL'}")
print(f"  F1 Score:           {f1:.4f}  (target: >= 0.87) {'PASS' if f1 >= 0.87 else 'FAIL'}")
print(f"  Staleness Enforce:  {staleness_enforcement:.4f}  (target: = 1.00) {'PASS' if staleness_enforcement >= 1.0 else 'FAIL'}")
print(f"\n  --- Secondary Metrics (Advisory) ---")
print(f"  Accuracy:                  {accuracy:.4f}")
print(f"  Near-Miss Rejection:       {near_miss_rejection_rate:.4f}  (target: >= 0.90)")
print(f"  Adversarial Rejection:     {adversarial_rejection_rate:.4f}  (target: >= 0.95)")
print(f"  Retrieval Hit Rate:        {retrieval_hit_rate:.4f}  (target: >= 0.95)")
print(f"  Mean Conf (positives):     {mean_confidence_positives:.4f}  (target: >= 0.88)")
print(f"  Mean Conf (negatives):     {mean_confidence_negatives:.4f}  (target: <= 0.50)")
print(f"  Latency P95:               {latency_p95}ms  (target: < 5000ms)")
print("=" * 60)

# COMMAND ----------

# MAGIC %md
# MAGIC ## Log to MLflow Experiment

# COMMAND ----------

mlflow.set_tracking_uri("databricks")
mlflow.set_experiment(EXPERIMENT_NAME)

with mlflow.start_run(run_name=f"router-eval-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}") as run:
    # Parameters
    mlflow.log_param("catalog", CATALOG)
    mlflow.log_param("schema", SCHEMA)
    mlflow.log_param("confidence_threshold", CONFIDENCE_THRESHOLD)
    mlflow.log_param("shrink_factor", SHRINK_FACTOR)
    mlflow.log_param("vs_endpoint", VS_ENDPOINT)
    mlflow.log_param("vs_top_k", VS_TOP_K)
    mlflow.log_param("judge_model", JUDGE_MODEL)
    mlflow.log_param("eval_dataset_size", eval_count)
    mlflow.log_param("valid_results", total_valid)

    # Primary metrics
    mlflow.log_metric("gate_precision", precision)
    mlflow.log_metric("gate_recall", recall)
    mlflow.log_metric("f1_score", f1)
    mlflow.log_metric("staleness_enforcement", staleness_enforcement)
    mlflow.log_metric("accuracy", accuracy)

    # Secondary metrics
    mlflow.log_metric("near_miss_rejection_rate", near_miss_rejection_rate)
    mlflow.log_metric("adversarial_rejection_rate", adversarial_rejection_rate)
    mlflow.log_metric("retrieval_hit_rate", retrieval_hit_rate)
    mlflow.log_metric("mean_confidence_positives", mean_confidence_positives)
    mlflow.log_metric("mean_confidence_negatives", mean_confidence_negatives)
    mlflow.log_metric("latency_p95_ms", latency_p95)
    mlflow.log_metric("error_count", len(errors))

    # Confusion matrix
    mlflow.log_metric("true_positives", tp)
    mlflow.log_metric("false_positives", fp)
    mlflow.log_metric("false_negatives", fn)
    mlflow.log_metric("true_negatives", tn)

    # Per-category accuracy
    for cat in set(r["category"] for r in valid_results):
        cat_results = [r for r in valid_results if r["category"] == cat]
        if cat_results:
            cat_accuracy = sum(1 for r in cat_results if r["is_correct"]) / len(cat_results)
            mlflow.log_metric(f"accuracy_{cat}", cat_accuracy)

    # Deployment gate pass/fail
    gate_passed = (precision >= 0.95 and recall >= 0.80 and staleness_enforcement >= 1.0)
    mlflow.log_metric("deployment_gate_passed", 1.0 if gate_passed else 0.0)

    print(f"MLflow run logged: {run.info.run_id}")
    print(f"  Experiment: {EXPERIMENT_NAME}")
    print(f"  Deployment gate: {'PASSED' if gate_passed else 'FAILED'}")

# COMMAND ----------

