false_positives = [r for r in valid_results if r["expected_lane"] == "analytical" and r["predicted_lane"] == "certified"]
if false_positives:
    print(f"\n{'='*60}")
    print(f"  FALSE POSITIVES ({len(false_positives)} cases) — CRITICAL")
