# MAGIC %md
# MAGIC ## Pass Metrics to Downstream Task

# COMMAND ----------

dbutils.jobs.taskValues.set(key="gate_precision", value=round(precision, 4))
dbutils.jobs.taskValues.set(key="gate_recall", value=round(recall, 4))
dbutils.jobs.taskValues.set(key="f1_score", value=round(f1, 4))
